    bdd_scenario! { id: "F9.5", fn_name: f9_5, persona: Alice, title: "Policy changes for one team do not affect calls from other teams", description: "Alice changes the rule set for one team while another team has its own rule set. The modified team observes the change and the other team keeps its prior behavior.", given: |ctx| { ctx.alice().await }, when: |alice| { alice.alice_w3_policy_change_is_team_scoped().await? }, then: |result, ctx| { assert_accepts(result, ctx, "PolicyTeamScope"); }, }
    bdd_scenario! { id: "F9.6", fn_name: f9_6, persona: Alice, title: "Global rules apply first, followed by team rules", description: "Alice configures global rules and team-specific rules together. Calls pass through the global rules first and the team rule provides the final decision when both choose the same kind of outcome.", given: |ctx| { ctx.alice().await }, when: |alice| { alice.alice_w3_global_then_team_rules().await? }, then: |result, ctx| { assert_accepts(result, ctx, "PolicyPrecedence"); }, }
